-- 세트 503: MariaDB 문제 해결 상황집: 접속 거부, 없는 DB·테이블, 중복 키, 접속 가득, 락 대기
-- 빈틈 보강 파일럿(docs/specs/spec_pilot_gap_sets.md). 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다.
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (503, 1, 'ERROR 1045: 비밀번호가 틀렸다', '앱이 쓰는 설정 파일 `/tmp/app.cnf` 로 접속하면 `ERROR 1045 (28000): Access denied for user ''app''@''localhost'' (using password: YES)` 가 납니다. 배포 문서에 적힌 올바른 비밀번호는 **`S3cret`** 입니다. 설정 파일을 고쳐, 접속해 `SELECT 1` 한 결과(`1`)를 `/tmp/ok.txt` 에 저장하세요.', '먼저 `mariadb --defaults-file=/tmp/app.cnf -e "SELECT 1"` 로 오류를 확인하세요. 접속 정보는 `[client]` 아래 `password=` 줄에 있습니다.', 'sed -i ''s/^password=.*/password=S3cret/'' /tmp/app.cnf
mariadb --defaults-file=/tmp/app.cnf -N -e ''SELECT 1'' > /tmp/ok.txt
cat /tmp/ok.txt

# 1045 = 계정은 있는데 비밀번호(또는 접속 호스트)가 맞지 않음. 먼저 설정 파일의 값이 맞는지 본다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE items (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT); INSERT INTO items VALUES (1,\\"apple\\",1000),(2,\\"pear\\",2000),(3,\\"grape\\",3000),(4,\\"peach\\",4000),(5,\\"plum\\",5000); DROP USER IF EXISTS \\"app\\"@\\"localhost\\"; CREATE USER \\"app\\"@\\"localhost\\" IDENTIFIED BY \\"S3cret\\"; GRANT ALL ON shop.* TO \\"app\\"@\\"localhost\\"; FLUSH PRIVILEGES;''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf; printf ''[client]\\\\nuser=app\\\\npassword=wrong\\\\n'' > /tmp/app.cnf"]', '["sh", "-c", "( mariadb --defaults-file=/tmp/app.cnf -N -e \\"SELECT 1\\" | grep -qx 1 ) && ( [ \\"$(cat /tmp/ok.txt)\\" = 1 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "설정 파일로 접속된다", "cmd": ["sh", "-c", "mariadb --defaults-file=/tmp/app.cnf -N -e \\"SELECT 1\\" | grep -qx 1"]}, {"label": "결과를 저장했다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/ok.txt)\\" = 1 ]"]}]', '[{"title": "MariaDB 오류 코드", "url": "https://mariadb.com/kb/en/mariadb-error-codes/"}]'),
  (503, 2, 'ERROR 1049: 없는 데이터베이스', '`/tmp/report.sh` 를 실행하면 `ERROR 1049 (42000): Unknown database ''shopp''` 가 납니다. 스크립트를 고쳐 **상품 수**를 `/tmp/count.txt` 에 저장하세요. (값은 5)', '오류 메시지에 나온 데이터베이스 이름과 실제 이름(`SHOW DATABASES;`)을 비교해 보세요. 스크립트 안의 이름을 고칩니다.', 'sed -i ''s/shopp/shop/'' /tmp/report.sh
sh /tmp/report.sh > /tmp/count.txt
cat /tmp/count.txt

# 1049 = 이름에 해당하는 데이터베이스가 없다. 보통 오타이거나 다른 서버를 보고 있다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE items (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT); INSERT INTO items VALUES (1,\\"apple\\",1000),(2,\\"pear\\",2000),(3,\\"grape\\",3000),(4,\\"peach\\",4000),(5,\\"plum\\",5000); DROP USER IF EXISTS \\"app\\"@\\"localhost\\"; CREATE USER \\"app\\"@\\"localhost\\" IDENTIFIED BY \\"S3cret\\"; GRANT ALL ON shop.* TO \\"app\\"@\\"localhost\\"; FLUSH PRIVILEGES;''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf; printf ''#!/bin/sh\\\\nmariadb -N shopp -e \\"SELECT COUNT(*) FROM items\\"\\\\n'' > /tmp/report.sh"]', '["sh", "-c", "( [ \\"$(cat /tmp/count.txt)\\" = 5 ] ) && ( ! grep -q shopp /tmp/report.sh )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "count.txt 가 5 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/count.txt)\\" = 5 ]"]}, {"label": "스크립트에서 오타가 사라졌다", "cmd": ["sh", "-c", "! grep -q shopp /tmp/report.sh"]}]', '[{"title": "MariaDB 오류 코드", "url": "https://mariadb.com/kb/en/mariadb-error-codes/"}]'),
  (503, 3, 'ERROR 1146: 없는 테이블', '`/tmp/report.sh` 를 실행하면 `ERROR 1146 (42S02): Table ''shop.item'' doesn''t exist` 가 납니다. 메시지에 **어느 데이터베이스의 어느 테이블**이 없다고 나오는지 읽고, 스크립트를 고쳐 **가장 비싼 상품의 가격**을 `/tmp/max.txt` 에 저장하세요. (값은 5000)', '`mariadb shop -e "SHOW TABLES;"` 로 실제 테이블 이름을 확인하세요. 오류 메시지의 `shop.item` 은 `데이터베이스.테이블` 입니다.', 'sed -i ''s/FROM item /FROM items /'' /tmp/report.sh
sh /tmp/report.sh > /tmp/max.txt
cat /tmp/max.txt

# 1146 메시지는 ''데이터베이스.테이블'' 로 알려 준다. 테이블 이름 오타인지, 데이터베이스를 잘못 골랐는지 가른다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE items (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT); INSERT INTO items VALUES (1,\\"apple\\",1000),(2,\\"pear\\",2000),(3,\\"grape\\",3000),(4,\\"peach\\",4000),(5,\\"plum\\",5000); DROP USER IF EXISTS \\"app\\"@\\"localhost\\"; CREATE USER \\"app\\"@\\"localhost\\" IDENTIFIED BY \\"S3cret\\"; GRANT ALL ON shop.* TO \\"app\\"@\\"localhost\\"; FLUSH PRIVILEGES;''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf; printf ''#!/bin/sh\\\\nmariadb -N shop -e \\"SELECT MAX(price) FROM item \\"\\\\n'' > /tmp/report.sh"]', '["sh", "-c", "( [ \\"$(cat /tmp/max.txt)\\" = 5000 ] ) && ( grep -q \\"FROM items\\" /tmp/report.sh )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "max.txt 가 5000 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/max.txt)\\" = 5000 ]"]}, {"label": "스크립트가 items 를 본다", "cmd": ["sh", "-c", "grep -q \\"FROM items\\" /tmp/report.sh"]}]', '[{"title": "MariaDB 오류 코드", "url": "https://mariadb.com/kb/en/mariadb-error-codes/"}]'),
  (503, 4, 'ERROR 1062: 중복된 키', '`/tmp/add.sql` 로 새 상품 `melon`(3500원)을 넣으면 `ERROR 1062 (23000): Duplicate entry ''3'' for key ''PRIMARY''` 가 납니다. 이미 있는 id 3(`grape`)은 **그대로 두고**, 스크립트를 고쳐 `melon` 이 **새 행으로** 들어가게 한 뒤 `mariadb shop < /tmp/add.sql` 로 실행하세요.', '`id` 는 `AUTO_INCREMENT` 기본 키입니다. 값을 직접 정하지 않으면 새 번호가 자동으로 붙습니다.', 'cat > /tmp/add.sql <<''SQL''
INSERT INTO items (name, price) VALUES (''melon'', 3500);
SQL
mariadb shop < /tmp/add.sql
mariadb shop -e ''SELECT * FROM items''

# 1062 = 기본 키·UNIQUE 값이 이미 있다. 기존 행을 덮어쓰는 게 아니라면 id 를 지정하지 않거나 다른 값을 쓴다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE items (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT); INSERT INTO items VALUES (1,\\"apple\\",1000),(2,\\"pear\\",2000),(3,\\"grape\\",3000),(4,\\"peach\\",4000),(5,\\"plum\\",5000); DROP USER IF EXISTS \\"app\\"@\\"localhost\\"; CREATE USER \\"app\\"@\\"localhost\\" IDENTIFIED BY \\"S3cret\\"; GRANT ALL ON shop.* TO \\"app\\"@\\"localhost\\"; FLUSH PRIVILEGES;''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf; printf \\"INSERT INTO items (id, name, price) VALUES (3, ''melon'', 3500);\\\\n\\" > /tmp/add.sql"]', '["sh", "-c", "( [ \\"$(mariadb -N shop -e \\"SELECT COUNT(*) FROM items WHERE name=''melon''\\")\\" = 1 ] ) && ( [ \\"$(mariadb -N shop -e \\"SELECT name FROM items WHERE id=3\\")\\" = grape ] ) && ( [ \\"$(mariadb -N shop -e \\"SELECT COUNT(*) FROM items\\")\\" = 6 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "melon 이 들어갔다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e \\"SELECT COUNT(*) FROM items WHERE name=''melon''\\")\\" = 1 ]"]}, {"label": "id 3 은 grape 그대로다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e \\"SELECT name FROM items WHERE id=3\\")\\" = grape ]"]}, {"label": "모두 6행이다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e \\"SELECT COUNT(*) FROM items\\")\\" = 6 ]"]}]', '[{"title": "MariaDB 오류 코드", "url": "https://mariadb.com/kb/en/mariadb-error-codes/"}]'),
  (503, 5, 'Too many connections: 접속이 가득 찼다', '앱 계정 `app`(비밀번호 `S3cret`)으로 접속하면 `ERROR 1040 (HY000): Too many connections` 가 납니다. 서버(root)로 접속해 **원인을 찾아 해결**한 뒤, `app` 계정으로 접속해 `SELECT 1` 한 결과(`1`)를 `/tmp/app_ok.txt` 에 저장하세요.

(root 는 이 상황에서도 접속할 수 있습니다.)', '`SHOW PROCESSLIST;` 로 누가 접속을 차지했는지, `SHOW VARIABLES LIKE ''max_connections'';` 로 한도를 보세요. 오래 붙은 세션을 `KILL` 하거나 한도를 올리면 됩니다.', 'for id in $(mariadb -N -e "SELECT id FROM information_schema.processlist WHERE user=''app''"); do mariadb -e "KILL $id"; done
sleep 1
mariadb -uapp -pS3cret -N -e ''SELECT 1'' > /tmp/app_ok.txt
cat /tmp/app_ok.txt

# 한도(max_connections)가 작거나 유휴 세션이 접속을 점유하면 1040. 원인 세션을 정리하고, 반복되면 한도·앱 접속 풀을 점검한다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE items (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT); INSERT INTO items VALUES (1,\\"apple\\",1000),(2,\\"pear\\",2000),(3,\\"grape\\",3000),(4,\\"peach\\",4000),(5,\\"plum\\",5000); DROP USER IF EXISTS \\"app\\"@\\"localhost\\"; CREATE USER \\"app\\"@\\"localhost\\" IDENTIFIED BY \\"S3cret\\"; GRANT ALL ON shop.* TO \\"app\\"@\\"localhost\\"; FLUSH PRIVILEGES;''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf; mariadb -e ''SET GLOBAL max_connections=4''; for i in 1 2 3 4; do nohup mariadb -uapp -pS3cret -e ''SELECT SLEEP(600)'' >/dev/null 2>&1 & done; sleep 2"]', '["sh", "-c", "( mariadb -uapp -pS3cret -N -e \\"SELECT 1\\" | grep -qx 1 ) && ( [ \\"$(cat /tmp/app_ok.txt)\\" = 1 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "app 으로 접속된다", "cmd": ["sh", "-c", "mariadb -uapp -pS3cret -N -e \\"SELECT 1\\" | grep -qx 1"]}, {"label": "결과를 저장했다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/app_ok.txt)\\" = 1 ]"]}]', '[{"title": "MariaDB 오류 코드", "url": "https://mariadb.com/kb/en/mariadb-error-codes/"}]'),
  (503, 6, 'Lock wait timeout: 막고 있는 세션 찾기', '`UPDATE items SET price=1500 WHERE id=1` 가 오래 멈췄다가 `ERROR 1205 ... Lock wait timeout exceeded` 로 실패합니다. 누군가 **COMMIT 하지 않은 트랜잭션**이 id 1 행을 쥐고 있습니다. 원인 세션을 찾아 `KILL` 한 뒤 그 `UPDATE` 를 성공시키세요.', '`information_schema.innodb_trx` 의 `trx_mysql_thread_id` 가 세션 번호입니다. 먼저 KILL 로 푼 뒤 UPDATE 를 실행합니다.', 'ID=$(mariadb -N -e ''SELECT trx_mysql_thread_id FROM information_schema.innodb_trx LIMIT 1'')
mariadb -e "KILL $ID"
sleep 1
mariadb shop -e ''UPDATE items SET price=1500 WHERE id=1''
mariadb -N shop -e ''SELECT price FROM items WHERE id=1''

# 1205 의 원인은 대개 오래 열린 트랜잭션. innodb_trx 로 찾고, 업무 영향 확인 후 KILL 한다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE items (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT); INSERT INTO items VALUES (1,\\"apple\\",1000),(2,\\"pear\\",2000),(3,\\"grape\\",3000),(4,\\"peach\\",4000),(5,\\"plum\\",5000); DROP USER IF EXISTS \\"app\\"@\\"localhost\\"; CREATE USER \\"app\\"@\\"localhost\\" IDENTIFIED BY \\"S3cret\\"; GRANT ALL ON shop.* TO \\"app\\"@\\"localhost\\"; FLUSH PRIVILEGES;''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf; nohup mariadb shop -e ''START TRANSACTION; UPDATE items SET price = price WHERE id = 1; SELECT SLEEP(600);'' >/dev/null 2>&1 & sleep 1"]', '["sh", "-c", "( [ \\"$(mariadb -N shop -e \\"SELECT price FROM items WHERE id=1\\")\\" = 1500 ] ) && ( [ \\"$(mariadb -N -e \\"SELECT COUNT(*) FROM information_schema.innodb_trx\\")\\" = 0 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "가격이 1500 이다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e \\"SELECT price FROM items WHERE id=1\\")\\" = 1500 ]"]}, {"label": "열린 트랜잭션이 없다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N -e \\"SELECT COUNT(*) FROM information_schema.innodb_trx\\")\\" = 0 ]"]}]', '[{"title": "MariaDB 오류 코드", "url": "https://mariadb.com/kb/en/mariadb-error-codes/"}]'),
  (503, 7, '1205 를 만났을 때 가장 먼저 할 일', '`ERROR 1205: Lock wait timeout exceeded; try restarting transaction` 을 만났습니다. **가장 먼저** 해야 할 일은 무엇인가요?', '이 오류는 내 쿼리가 아니라 다른 쪽 때문에 생기는 경우가 많습니다. 원인을 확인하기 전에 설정이나 서버를 건드리지 마세요.', NULL, NULL, '[]', 'choice', '["서버를 재시작한다", "`max_connections` 를 두 배로 늘린다", "막고 있는 트랜잭션을 찾는다 (information_schema.innodb_trx)", "테이블을 삭제하고 다시 만든다"]', 2, '1205 는 락 대기가 한도를 넘었다는 뜻입니다. 락을 쥔 트랜잭션을 찾아 원인을 보고 필요하면 그 세션을 KILL 합니다. 재시작이나 테이블 재생성은 과한 조치이고, max_connections 는 접속 수 한도라 관계가 없습니다.', NULL, NULL, NULL, NULL),
  (503, 8, '현재 열린 접속 수 보기', '지금 서버에 **열려 있는 접속 수**를 보는 문장입니다. 빈칸을 채우세요.', '지금 이 순간의 값이 필요합니다. 서버 시작 이후의 최고치가 아닙니다.', NULL, NULL, '[]', 'fill', '["Threads_connected", "Max_used_connections", "Connection_errors", "Open_tables"]', NULL, '`Threads_connected` 는 지금 열려 있는 접속 수입니다. `Max_used_connections` 는 서버 시작 이후의 최고치이고, 이 값이 `max_connections` 에 닿았다면 1040 이 난 적이 있다는 뜻입니다.', '[0]', 'SHOW STATUS LIKE ''{0}'';', NULL, NULL),
  (503, 9, 'Too many connections 해결 순서', '`app` 접속이 `Too many connections` 로 거절될 때 조치 순서대로 놓으세요.', '문제를 알아챈 뒤, 접속 수 한도와 상관없이 들어갈 수 있는 계정으로 원인을 살펴보고 정리하세요. 해결됐는지는 마지막에 확인합니다.', NULL, NULL, '[]', 'order', '["SHOW PROCESSLIST 로 접속을 차지한 세션 보기", "불필요한 세션을 KILL 하기", "app 계정으로 다시 접속해 보기", "app 접속이 1040 으로 거절됨을 확인", "root 로 서버에 접속하기"]', NULL, '먼저 오류를 확인하고, 한도와 무관하게 들어갈 수 있는 관리자 계정으로 접속합니다. PROCESSLIST 로 점유한 세션을 보고 불필요한 것을 KILL 한 뒤, 같은 계정으로 다시 접속해 해결됐는지 확인합니다.', '[3, 4, 0, 1, 2]', NULL, NULL, NULL);
